INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wagamama-fairy-mirumo-de-pon---dokidoki-memorial-panic-jcaravan', 'GAMEBOYADVANCE', 'Wagamama Fairy Mirumo de Pon - Dokidoki Memorial Panic (J)(Caravan)', '2003', 'Adventure', 'Hudson Soft', '1', 'Anime Adventure', 'Memory-based puzzle and adventure game.', 'Solve puzzles and win the Memorial Panic tournament.', 'Fun and cute memory challenges with Mirumo.', 'This Mirumo de Pon entry focuses on logic and memory puzzles. Perfect for fans of the series, it combines adorable visuals with engaging handheld brain-teasers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wagamama-fairy-mirumo-de-pon-nazo-no-kagi-to-shinjitsu-no-tobira-jcaravan', 'GAMEBOYADVANCE', 'Wagamama Fairy Mirumo de Pon Nazo no Kagi to Shinjitsu no Tobira (J)(Caravan)', '2004', 'Adventure', 'Hudson Soft', '1', 'Anime Adventure', 'Mystery-solving adventure with logic puzzles.', 'Unlock the secret doors and find the legendary Golden Key.', 'A magical mystery quest for the GBA.', 'Nazo no Kagi to Shinjitsu no Tobira expands the Mirumo world. Explore detailed environments and use fairy magic to uncover truths and solve environmental riddles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wagamama-fairy-mirumo-de-pon-ougon-maracas-no-densetsu-jpolla', 'GAMEBOYADVANCE', 'Wagamama Fairy Mirumo de Pon Ougon Maracas no Densetsu (J)(Polla)', '2004', 'Adventure', 'Hudson Soft', '1', 'Anime Adventure', '2D adventure platformer with rhythmic elements.', 'Find the legendary Golden Maracas and save the fairy forest.', 'A musical and magical journey with the Muglox fairies.', 'Ougon Maracas no Densetsu is a vibrant platformer. Use Mirumo''s magical instruments to interact with the world and defeat bosses in this cheerful handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wagamama-fairy-mirumo-de-pon-taisen-mahoudrama-jprost', 'GAMEBOYADVANCE', 'Wagamama Fairy Mirumo De Pon Taisen Mahoudrama (J)(Prost)', '2005', 'Strategy', 'Hudson Soft', '2', 'Tactical RPG', 'Board-game style strategy with magical battles.', 'Win the magical drama competition against your fairy rivals.', 'A competitive and colorful fairy board game.', 'Taisen Mahoudrama features strategic tile-based movement and card-like battles. Outsmart the other fairies using special items and magical spells to win the grand prize.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wagamama-fairy-miruro-de-pon!-yume-no-kakera-jcaravan', 'GAMEBOYADVANCE', 'Wagamama Fairy Miruro de Pon! Yume no Kakera (J)(Caravan)', '2005', 'Adventure', 'Hudson Soft', '1', 'Anime Adventure', 'Adventure-sim with item collection and mini-games.', 'Collect the "Dream Fragments" to restore the fairy world.', 'A sweet and relaxing fairy adventure for GBA.', 'Yume no Kakera is a peaceful title focused on exploration and social interaction. Help the residents of the fairy and human worlds while playing fun, short mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wakeboarding-unleashed-uindependent', 'GAMEBOYADVANCE', 'Wakeboarding Unleashed (U)(Independent)', '2003', 'Sports', 'Shaba Games', '2', 'Extreme Sports', '3D-style arcade wakeboarding with tricks.', 'Perform massive stunts and reach the goal within the time limit.', 'High-speed water sports action with extreme tricks.', 'Wakeboarding Unleashed features fluid physics and a variety of ocean and lake environments. Master the tow-rope mechanics to pull off flips and grinds in this intense racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wakeboarding-unleashed-umenace', 'GAMEBOYADVANCE', 'Wakeboarding Unleashed (U)(Menace)', '2003', 'Sports', 'Shaba Games', '2', 'Extreme Sports', '3D-style arcade wakeboarding with tricks.', 'Perform massive stunts and reach the goal within the time limit.', 'High-speed water sports action with extreme tricks.', 'Wakeboarding Unleashed features fluid physics and a variety of ocean and lake environments. Master the tow-rope mechanics to pull off flips and grinds in this intense racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('waliou-zhizao-cwrg', 'GAMEBOYADVANCE', 'Waliou Zhizao (C)(WRG)', '2004', 'Platformer', 'Nintendo', '1', 'Classic Platformer', 'Micro-game collection (Chinese version of WarioWare).', 'Clear rapid-fire mini-games to reach the final boss.', 'Intense and bizarre micro-game action.', 'Waliou Zhizao is the localized version of WarioWare, Inc. Experience the same fast-paced, 5-second challenges that defined a new genre of gaming, now for the Chinese market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wanko-de-kururin-wancle-jcaravan', 'GAMEBOYADVANCE', 'Wanko de Kururin Wancle (J)(Caravan)', '2003', 'Puzzle', 'Mitchell', '1', 'Physics Puzzle', 'Puzzle and pet simulation featuring cute dogs.', 'Clear blocks to help the puppies find their way home.', 'A sweet and addictive puppy-themed puzzle game.', 'Wanko de Kururin Wancle combines tile-matching with adorable pet interactions. Solve puzzles to unlock new dog breeds and items for your virtual canine friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wanko-mix-chiwanko-world-jindependent', 'GAMEBOYADVANCE', 'Wanko Mix Chiwanko World (J)(Independent)', '2004', 'Simulation', 'Alpha Unit', '1', 'Pet Simulation', 'Social simulation and pet raising for dog lovers.', 'Raise the perfect Chihuahua and win international shows.', 'A detailed Chihuahua-focused pet simulator.', 'Wanko Mix: Chiwanko World lets you feed, groom, and train your dogs. Explore the neighborhood and compete in various activities in this cozy Japanese GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wannyan-doubutsu-byouin-jrising-sun', 'GAMEBOYADVANCE', 'Wannyan Doubutsu Byouin (J)(Rising Sun)', '2003', 'Simulation', 'Marvelous Interactive', '1', 'Veterinary Simulation', 'Medical simulation and pet care adventure.', 'Treat sick animals and manage a successful vet clinic.', 'A heartwarming animal doctor simulation.', 'Wannyan Doubutsu Byouin (Cat & Dog Animal Hospital) tasks you with diagnosing and curing cute pets. Learn about veterinary care while building relationships with your fuzzy patients.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wannyan-idol-gakuen-jcaravan', 'GAMEBOYADVANCE', 'Wannyan Idol Gakuen (J)(Caravan)', '2004', 'Simulation', 'Marvelous Interactive', '1', 'Idol Simulation', 'Idol simulation and talent management.', 'Train your character to become the top singing sensation.', 'A stylish Japanese idol-career simulator.', 'Wannyan Idol Gakuen focuses on rhythm games and fashion. Manage your schedule, practice your dance moves, and perform on stage to reach superstardom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wanwan-meitantei-jrising-sun', 'GAMEBOYADVANCE', 'WanWan Meitantei (J)(Rising Sun)', '2003', 'Adventure', 'Marvelous Interactive', '1', 'Detective Adventure', 'Mystery-adventure starring a detective dog.', 'Sniff out clues and solve crimes in the animal kingdom.', 'A unique and charming "dog-tective" adventure.', 'WanWan Meitantei features investigative gameplay from a canine perspective. Use your nose and logic to track down suspects and solve neighborhood mysteries.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wario-land-4---bird-challenge', 'GAMEBOYADVANCE', 'Wario Land 4 - Bird Challenge', '2001', 'Platformer', 'Nintendo', '1', 'Challenge Platformer', 'High-difficulty RomHack (Wario Land 4).', 'Survive a brutal gauntlet of bird-themed platforming levels.', 'A hardcore challenge for Wario Land veterans.', 'Bird Challenge ramps up the difficulty of the original game, requiring pixel-perfect jumps and masterful use of Wario''s dash to reach the exit before the timer hits zero.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wario-land-4---burning-nightmares', 'GAMEBOYADVANCE', 'Wario Land 4 - Burning Nightmares', '2001', 'Platformer', 'Nintendo', '1', 'Challenge Platformer', 'Horror-themed RomHack (Wario Land 4).', 'Navigate creepy, reworked levels filled with nightmare foes.', 'A dark and spooky twist on the classic Wario gameplay.', 'Burning Nightmares reimagines Wario''s quest with a horror aesthetic. Experience familiar mechanics in unsettling new environments with increased enemy density.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wario-land-4---custom-block-master', 'GAMEBOYADVANCE', 'Wario Land 4 - Custom Block Master', '2001', 'Platformer', 'Nintendo', '1', 'Challenge Platformer', 'Level-editor style RomHack (Wario Land 4).', 'Master complex block-based puzzles in custom-built stages.', 'A brain-teasing overhaul of the Wario Land formula.', 'Custom Block Master focuses on Wario''s ability to manipulate the environment. Solve intricate puzzles that require deep knowledge of the game''s block mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wario-land-4---endless-laps', 'GAMEBOYADVANCE', 'Wario Land 4 - Endless Laps', '2001', 'Platformer', 'Nintendo', '1', 'Challenge Platformer', 'Racing-focused RomHack (Wario Land 4).', 'Complete the longest laps and beat the clock in custom stages.', 'A high-speed race against time for GBA.', 'Endless Laps emphasizes the "Escape" phase of Wario Land 4. Navigate through long, winding levels that test your speed and ability to maintain momentum.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wario-land-4---seaside-ruins', 'GAMEBOYADVANCE', 'Wario Land 4 - Seaside Ruins', '2001', 'Platformer', 'Nintendo', '1', 'Challenge Platformer', 'Themed RomHack (Wario Land 4).', 'Explore new aquatic ruins and find hidden treasures.', 'A refreshing and scenic custom adventure for Wario.', 'Seaside Ruins offers a new set of levels with a coastal theme. Enjoy creative level design and new secret placements that breathe fresh life into the classic engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wario-land-4---time-attack-edition-ver15', 'GAMEBOYADVANCE', 'Wario Land 4 - Time Attack Edition ver1.5', '2001', 'Platformer', 'Nintendo', '1', 'Time Trial Platformer', 'Competitive speed-running RomHack (Wario Land 4).', 'Beat the developer''s times in optimized speed-run levels.', 'The ultimate test of speed for Wario Land 4 fans.', 'Time Attack Edition is designed for efficiency. Every level is tweaked to support high-speed routes, making it the perfect choice for competitive GBA platforming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wario-land-4-emode7', 'GAMEBOYADVANCE', 'Wario Land 4 (E)(Mode7)', '2001', 'Platformer', 'Nintendo', '1', 'Platform Adventure', '2D action platformer with transformational mechanics.', 'Enter the legendary pyramid and recover the golden treasures.', 'A masterpiece of 2D platforming and animation.', 'Wario Land 4 is a GBA essential. Featuring incredible sprite work and a unique health system where damage causes transformations, it’s a brilliant mix of exploration and puzzle-solving.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wario-land-4-jeurasia', 'GAMEBOYADVANCE', 'Wario Land 4 (J)(Eurasia)', '2001', 'Platformer', 'Nintendo', '1', 'Platform Adventure', '2D action platformer with transformational mechanics.', 'Enter the legendary pyramid and recover the golden treasures.', 'A masterpiece of 2D platforming and animation.', 'Wario Land 4 is a GBA essential. Featuring incredible sprite work and a unique health system where damage causes transformations, it’s a brilliant mix of exploration and puzzle-solving.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wario-land-4:-parallel-world', 'GAMEBOYADVANCE', 'Wario Land 4: Parallel World', '2001', 'Platformer', 'Nintendo', '1', 'Experimental Platformer', 'Total overhaul RomHack (Wario Land 4).', 'Journey through a completely new world with original levels.', 'An unofficial sequel-sized expansion for Wario.', 'Parallel World features entirely new level layouts, custom music, and a shifted difficulty curve. It’s one of the most comprehensive fan projects available for the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wario-land-4:-pt-like-moveset-conversion', 'GAMEBOYADVANCE', 'Wario Land 4: PT-like Moveset Conversion', '2001', 'Platformer', 'Nintendo', '1', 'Experimental Platformer', 'Gameplay-mod RomHack (Wario Land 4).', 'Experience the game with a moveset inspired by Pizza Tower.', 'A fast-paced modern spin on classic Wario controls.', 'This conversion updates Wario''s physics and dash mechanics to be faster and more aggressive, inspired by the indie hit Pizza Tower, changing how you approach every level.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wario-land-advance-cwrg', 'GAMEBOYADVANCE', 'Wario Land Advance (C)(WRG)', '2001', 'Platformer', 'Nintendo', '1', 'Classic Platformer', '2D action platformer (Chinese version).', 'Enter the legendary pyramid and recover the golden treasures.', 'A masterpiece of 2D platforming and animation.', 'Wario Land Advance is the localized version of Wario''s GBA debut. Experience the same high-quality platforming and treasure hunting that made the series a handheld legend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wario-ware---twisted!-no-gyro-fix', 'GAMEBOYADVANCE', 'Wario Ware - Twisted! (No Gyro Fix)', '2005', 'Mini-Games', 'Nintendo', '1', 'Motion Mini-Games', 'Micro-game collection (RomHack for standard controllers).', 'Complete spinning mini-games using the D-pad instead of gyro.', 'A clever fix to play WarioWare Twisted! without a sensor.', 'This "No Gyro Fix" allows players to enjoy the brilliant rotation-based micro-games of WarioWare Twisted! using standard buttons, making it playable on all emulators and consoles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wario-ware-inc-ecezar', 'GAMEBOYADVANCE', 'Wario Ware Inc (E)(Cezar)', '2003', 'Mini-Games', 'Nintendo', '1', 'Party Mini-Games', 'Collection of 5-second micro-games.', 'React quickly to clear a barrage of weird and funny tasks.', 'The birth of the most creative genre on GBA.', 'WarioWare, Inc.: Mega Microgames! is a frantic masterpiece. With over 200 "micro-games" that last only seconds, it’s a fast-paced, surreal, and addictive experience unlike any other.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wario-ware-inc-uprecision', 'GAMEBOYADVANCE', 'Wario Ware Inc (U)(Precision)', '2003', 'Mini-Games', 'Nintendo', '1', 'Party Mini-Games', 'Collection of 5-second micro-games.', 'React quickly to clear a barrage of weird and funny tasks.', 'The birth of the most creative genre on GBA.', 'WarioWare, Inc.: Mega Microgames! is a frantic masterpiece. With over 200 "micro-games" that last only seconds, it’s a fast-paced, surreal, and addictive experience unlike any other.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wario-ware-twisted!-ueternity', 'GAMEBOYADVANCE', 'Wario Ware Twisted! (U)(Eternity)', '2005', 'Mini-Games', 'Nintendo', '1', 'Motion Mini-Games', 'Gyro-based micro-game collection.', 'Spin your GBA to clear over 200 rapid-fire challenges.', 'Innovative rotation-based micro-game madness.', 'WarioWare Twisted! is a technical marvel for the GBA. Using a built-in gyro sensor, you must tilt and spin your console to complete surreal 5-second tasks in Wario''s most creative adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('watashi-no-make-salon-jmugs', 'GAMEBOYADVANCE', 'Watashi No Make Salon (J)(Mugs)', '2003', 'Simulation', 'MTO', '1', 'Fashion Simulation', 'Makeup and fashion simulation.', 'Design the perfect look for your clients in your own salon.', 'A charming Japanese beauty and style simulator.', 'Watashi No Make Salon lets you run a professional makeup studio. Choose from various cosmetics, hairstyles, and accessories to satisfy your customers and grow your business.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('weekend-miljonairs-ngbanow', 'GAMEBOYADVANCE', 'Weekend Miljonairs (N)(GBANow)', '2003', 'Trivia', 'ELSPA', '1', 'Game Show', 'Trivia game show simulation.', 'Answer 15 questions to win a virtual million euros.', 'The Dutch version of the famous "Millionaire" show.', 'Weekend Miljonairs brings the tension of the TV hit to the GBA. Use your lifelines wisely and climb the money ladder in this faithful Dutch language adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wer-wird-millionar-g-q', 'GAMEBOYADVANCE', 'Wer Wird Millionar (G)(-Q)', '2003', 'Trivia', 'ELSPA', '1', 'Game Show', 'Trivia game show simulation.', 'Answer 15 questions to win a virtual million euros.', 'The German version of the famous "Millionaire" show.', 'Wer Wird Millionär? features the iconic music and atmosphere of the German show. Test your general knowledge and see if you have what it takes to reach the top prize.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('whac-a-mole-utrashman', 'GAMEBOYADVANCE', 'Whac-a-Mole (U)(Trashman)', '2004', 'Arcade', 'Namco', '1', 'Reflex Arcade', 'Arcade-style reaction and timing game.', 'Hit the moles as they pop up to reach high scores.', 'Classic carnival fun on your Game Boy Advance.', 'Whac-a-Mole brings the arcade favorite to the handheld. Test your reflexes across multiple modes and increasingly difficult stages in this fast-paced casual game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('whistle-jcezar', 'GAMEBOYADVANCE', 'Whistle (J)(Cezar)', '2002', 'Sports', 'Konami', '2', 'Soccer Simulation', 'Soccer management and strategy RPG.', 'Lead your team through the Japanese league to glory.', 'A deep and strategic soccer management quest.', 'Whistle! (based on the manga) combines sports simulation with an engaging story mode. Scout players, set tactics, and experience the journey of a rising soccer star.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('who-wants-to-be-a-millionaire---junior-eindependent', 'GAMEBOYADVANCE', 'Who Wants to Be a Millionaire - Junior (E)(Independent)', '2001', 'Trivia', 'ELSPA', '1', 'Game Show', 'Trivia game show for younger players.', 'Answer age-appropriate questions to win the top prize.', 'A family-friendly version of the classic trivia show.', 'Who Wants to Be a Millionaire: Junior Edition features questions tailored for children. It’s an educational and fun way for younger fans to experience the thrill of the hot seat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('who-wants-to-be-a-millionaire-aindependent', 'GAMEBOYADVANCE', 'Who Wants To Be A Millionaire (A)(Independent)', '2000', 'Trivia', 'ELSPA', '1', 'Game Show', 'Trivia game show simulation.', 'Reach the final question to win the virtual jackpot.', 'The Australian edition of the popular trivia franchise.', 'Who Wants To Be A Millionaire (AU) captures the specific flavor of the Australian show. Test your wits against a diverse bank of questions in this portable trivia challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('who-wants-to-be-a-millionaire-evenom', 'GAMEBOYADVANCE', 'Who Wants to Be a Millionaire (E)(Venom)', '2000', 'Trivia', 'ELSPA', '1', 'Game Show', 'Trivia game show simulation.', 'Reach the final question to win the virtual jackpot.', 'The classic UK/Global edition of the trivia show.', 'Who Wants to Be a Millionaire is a faithful recreation of the TV experience. Use "Phone-a-Friend" or "50:50" to navigate through tough questions on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('who-wants-to-be-a-millionaire-2nd-edition-evenom', 'GAMEBOYADVANCE', 'Who Wants to be a Millionaire 2nd Edition (E)(Venom)', '2001', 'Trivia', 'ELSPA', '1', 'Game Show', 'Updated trivia game show simulation.', 'Answer a new set of questions to reach the million.', 'The expanded second edition of the hit trivia game.', 'Who Wants to Be a Millionaire 2nd Edition offers thousands of new questions. Experience the same high-stakes gameplay with updated content for long-lasting replayability.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wing-commander-prophecy-esuxxors', 'GAMEBOYADVANCE', 'Wing Commander Prophecy (E)(Suxxors)', '2003', 'Shooter', 'Origin Systems', '1', 'Space Combat', '3D space combat simulation.', 'Defend the human fleet from the alien Nephilim threat.', 'Epic and immersive space-faring dogfights.', 'Wing Commander Prophecy is a technical showcase for GBA. Pilot advanced fighters in a full 3D environment, completing mission-based objectives in this legendary sci-fi saga.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wing-commander-prophecy-uvenom', 'GAMEBOYADVANCE', 'Wing Commander Prophecy (U)(Venom)', '2003', 'Shooter', 'Origin Systems', '1', 'Space Combat', '3D space combat simulation.', 'Defend the human fleet from the alien Nephilim threat.', 'Epic and immersive space-faring dogfights.', 'Wing Commander Prophecy is a technical showcase for GBA. Pilot advanced fighters in a full 3D environment, completing mission-based objectives in this legendary sci-fi saga.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wings-eindependent', 'GAMEBOYADVANCE', 'Wings (E)(Independent)', '2002', 'Shooter', 'Cinemaware', '1', 'Aerial Combat', 'WWI aerial combat and dogfighting.', 'Pilot biplanes in intense missions over the battlefields.', 'A classic arcade-style aerial combat port.', 'Wings brings the cinematic WWI flight experience to GBA. From strafing runs to tactical dogfights, experience the life of an ace pilot in this polished action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wings-urapid-fire', 'GAMEBOYADVANCE', 'Wings (U)(Rapid Fire)', '2002', 'Shooter', 'Cinemaware', '1', 'Aerial Combat', 'WWI aerial combat and dogfighting.', 'Pilot biplanes in intense missions over the battlefields.', 'A classic arcade-style aerial combat port.', 'Wings brings the cinematic WWI flight experience to GBA. From strafing runs to tactical dogfights, experience the life of an ace pilot in this polished action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('winnie-the-poohs-rumbly-tumbly-adventure-ecaravan', 'GAMEBOYADVANCE', 'Winnie the Pooh''s Rumbly Tumbly Adventure (E)(Caravan)', '2005', 'Adventure', 'Hulabee Entertainment', '1', 'Children Adventure', '2D side-scrolling adventure for kids.', 'Help Pooh find honey and explore the Hundred Acre Wood.', 'A sweet and charming adventure for younger players.', 'Winnie the Pooh''s Rumbly Tumbly Adventure features beautiful graphics and gentle gameplay. Solve simple puzzles and interact with Piglet, Tigger, and Eeyore.');
