INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yakusoku-no-chi-riviera-jcaravan', 'GAMEBOYADVANCE', 'Yakusoku no Chi Riviera (J)(Caravan)', '2002', 'RPG', 'Sting', '1', 'Tactical RPG', 'Turn-based RPG with exploration and card mechanics.', 'Journey to the promised land of Riviera to save the world.', 'A stunning and unique cult-classic JRPG.', 'Riviera: The Promised Land (Yakusoku no Chi Riviera) features gorgeous art and a unique branching story. Manage your limited item uses and build relationships in this innovative and beautiful RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yakyutsuku-advance-jstone-arts', 'GAMEBOYADVANCE', 'Yakyutsuku Advance (J)(Stone Arts)', '2003', 'Simulation', 'Smilebit', '1', 'Baseball Management', 'Baseball management and simulation.', 'Build a professional baseball team and win the league.', 'Deep and strategic Japanese baseball management.', 'Yakyutsuku Advance puts you in the role of a team owner and manager. Scout players, develop facilities, and set match-day tactics in this comprehensive sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yaoxi-dao-cwrg', 'GAMEBOYADVANCE', 'Yaoxi Dao (C)(WRG)', '2003', 'Action', 'IGS', '1', 'Action Platformer', '2D side-scrolling platformer (Chinese release).', 'Navigate through treacherous levels to reach the goal.', 'A rare and colorful handheld platforming adventure.', 'Yaoxi Dao features classic GBA-style platforming with vibrant environments. Use your agility to overcome traps and defeat enemies in this unique region-exclusive title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yggdra-union---well-never-fight-alone-urising-sun', 'GAMEBOYADVANCE', 'Yggdra Union - We''ll Never Fight Alone (U)(Rising Sun)', '2006', 'RPG', 'Sting', '1', 'Tactical RPG', 'Tactical turn-based RPG with the "Union" system.', 'Lead Princess Yggdra''s army to reclaim the kingdom of Fantasinia.', 'A hardcore and visually stunning strategy masterpiece.', 'Yggdra Union is famous for its high difficulty and innovative mechanics. Use character "Unions" to launch massive attacks and manage your card-based deck in this epic tactical journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yggdra-union-eindependent', 'GAMEBOYADVANCE', 'Yggdra Union (E)(Independent)', '2006', 'RPG', 'Sting', '1', 'Tactical RPG', 'Tactical turn-based RPG with the "Union" system.', 'Lead Princess Yggdra''s army to reclaim the kingdom of Fantasinia.', 'A hardcore and visually stunning strategy masterpiece.', 'Yggdra Union is famous for its high difficulty and innovative mechanics. Use character "Unions" to launch massive attacks and manage your card-based deck in this epic tactical journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yggdra-union-jcaravan', 'GAMEBOYADVANCE', 'Yggdra Union (J)(Caravan)', '2006', 'RPG', 'Sting', '1', 'Tactical RPG', 'Tactical turn-based RPG with the "Union" system.', 'Lead Princess Yggdra''s army to reclaim the kingdom of Fantasinia.', 'A hardcore and visually stunning strategy masterpiece.', 'Yggdra Union is famous for its high difficulty and innovative mechanics. Use character "Unions" to launch massive attacks and manage your card-based deck in this epic tactical journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yoshi-smk', 'GAMEBOYADVANCE', 'Yoshi (SMK)', '2001', 'Platformer', 'Nintendo', '1', 'Platformer', 'Puzzle-platformer or fan-made conversion.', 'Guide Yoshi through levels to solve puzzles and clear stages.', 'A charming puzzle adventure starring Yoshi.', 'Yoshi (SMK) is a classic title featuring everyone''s favorite green dinosaur. Use logic and quick thinking to match blocks and clear levels in this iconic and friendly handheld experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yoshi-no-banyu-inryoku-jwrg', 'GAMEBOYADVANCE', 'Yoshi no Banyu Inryoku (J)(WRG)', '2005', 'Puzzle', 'Nintendo', '1', 'Puzzle', 'Gravity-based platformer with gyro-sensor controls.', 'Tilt the world to move Yoshi and solve puzzles.', 'A unique gravity-defying Yoshi adventure.', 'Yoshi no Banyu Inryoku (Yoshi Topsy-Turvy) uses a built-in tilt sensor. Rotate your GBA to change gravity, roll boulders, and climb walls in this innovative and artistic platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yoshi-sample-gba-tech-demo', 'GAMEBOYADVANCE', 'Yoshi Sample (GBA Tech Demo)', '2001', 'Tech Demo', 'Nintendo', '1', 'Demo', 'Technical demonstration of GBA hardware.', 'Explore a small environment to test Yoshi''s movement.', 'A rare glimpse into GBA development history.', 'The Yoshi Sample Tech Demo was used to showcase the GBA''s scaling and rotation capabilities. While short, it offers a fascinating look at the technical roots of Yoshi’s handheld adventures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yoshi-topsy-turvy-utrashman', 'GAMEBOYADVANCE', 'Yoshi Topsy-Turvy (U)(TrashMan)', '2005', 'Platformer', 'Nintendo', '1', 'Platformer', 'Gravity-based platformer with gyro-sensor controls.', 'Tilt the world to move Yoshi and solve puzzles.', 'A unique gravity-defying Yoshi adventure.', 'Yoshi Topsy-Turvy is a physics-based platformer where your movements tilt the entire stage. Master the tilt mechanics to navigate hazardous environments and defeat enemies in style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yoshis-island-sma-3-colour-restoration', 'GAMEBOYADVANCE', 'Yoshi''s Island (SMA 3) Colour Restoration', '2002', 'Platformer', 'Nintendo', '1', 'Platformer', '2D platformer with enhanced visual palette (RomHack).', 'Protect Baby Mario and reach the end of each stage.', 'The definitive visual version of a SNES classic.', 'Yoshi''s Island (SMA 3) Colour Restoration is a fan-made patch that restores the original SNES color depth, removing the GBA''s brightness wash for a vibrant, professional-grade visual experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yoshis-universal-gravitation-eendless-piracy', 'GAMEBOYADVANCE', 'Yoshi''s Universal Gravitation (E)(Endless Piracy)', '2005', 'Platformer', 'Nintendo', '1', 'Platformer', 'Gravity-based platformer with gyro-sensor controls.', 'Tilt the world to move Yoshi and solve puzzles.', 'A unique gravity-defying Yoshi adventure.', 'Yoshi''s Universal Gravitation challenges you to manipulate gravity by tilting your handheld. Use environmental physics to swing on pendulums and flatten enemies in this creative GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('youkaidou-jindependent', 'GAMEBOYADVANCE', 'Youkaidou (J)(Independent)', '2004', 'Adventure', 'Spike Chunsoft', '1', 'Adventure', 'Traditional Japanese board-game with card elements.', 'Outsmart opponents in a game of strategy and luck.', 'A classic and atmospheric Japanese tabletop game.', 'Youkaidou features deep strategic gameplay rooted in Japanese folklore. Manage your resources and navigate the board to achieve victory in this polished and rare GBA simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-yu-hakusho---spirit-detective-erising-sun', 'GAMEBOYADVANCE', 'Yu Yu Hakusho - Spirit Detective (E)(Rising Sun)', '2003', 'Action RPG', 'Treasure', '1', 'Action RPG', 'Action-adventure with spirit-based combat.', 'Relive the first saga of the anime as Yusuke Urameshi.', 'Dark and intense supernatural action for GBA.', 'Yu Yu Hakusho: Spirit Detective follows the journey of the Spirit Detective. Fight demons, master the Spirit Gun, and explore iconic locations from the hit anime series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-yu-hakusho---spirit-detective-umode7', 'GAMEBOYADVANCE', 'Yu Yu Hakusho - Spirit Detective (U)(Mode7)', '2003', 'Action RPG', 'Treasure', '1', 'Action RPG', 'Action-adventure with spirit-based combat.', 'Relive the first saga of the anime as Yusuke Urameshi.', 'Dark and intense supernatural action for GBA.', 'Yu Yu Hakusho: Spirit Detective follows the journey of the Spirit Detective. Fight demons, master the Spirit Gun, and explore iconic locations from the hit anime series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-yu-hakusho---tournament-tactics-uvenom', 'GAMEBOYADVANCE', 'Yu Yu Hakusho - Tournament Tactics (U)(Venom)', '2004', 'Strategy RPG', 'Treasure', '1', 'Strategy RPG', 'Turn-based tactical strategy with RPG elements.', 'Lead Yusuke''s team through the Dark Tournament.', 'Deep and strategic tactical combat for anime fans.', 'Yu Yu Hakusho: Tournament Tactics brings grid-based strategy to the GBA. Manage your team''s stats, choose your battles, and survive the most dangerous tournament in the demon world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh-duel-monsters-expert-2006-jwrg', 'GAMEBOYADVANCE', 'Yu-Gi-Oh Duel Monsters Expert 2006 (J)(WRG)', '2006', 'Card Battle', 'Konami', '1', 'Card Game', 'High-level TCG simulation with thousands of cards.', 'Build the ultimate deck and win the 2006 world circuit.', 'The most comprehensive Yu-Gi-Oh! sim on GBA.', 'Yu-Gi-Oh! Duel Monsters Expert 2006 features over 2,000 cards and advanced AI. It is widely considered the peak of the GBA series for competitive deck building and dueling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh-pokeduel', 'GAMEBOYADVANCE', 'Yu-Gi-Oh POKeDUEL', '2005', 'Card Battle', 'Konami', '1', 'Card Game', 'Creature-collection RPG (RomHack).', 'Battle and trade using Yu-Gi-Oh! monsters in a Pokémon world.', 'A creative crossover between two massive franchises.', 'Yu-Gi-Oh POKeDUEL replaces Pokémon with iconic Duel Monsters. Explore a new world, "catch" monsters like Blue-Eyes White Dragon, and duel your way to the top of this unique hack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!---destiny-board-traveler-esupplex', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! - Destiny Board Traveler (E)(Supplex)', '2004', 'Board Game', 'Konami', '1', 'Board Game', 'Strategy board-game with card-battle elements.', 'Navigate the board and defeat rivals in tactical duels.', 'A unique board-game spin-off of the Yu-Gi-Oh! series.', 'Yu-Gi-Oh! Destiny Board Traveler combines classic board game movement with card dueling mechanics. Strategize your placement and use your deck to dominate the field.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!---sugoroku-no-sugoroku-jcezar', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! - Sugoroku no Sugoroku (J)(Cezar)', '2005', 'Board Game', 'Konami', '1', 'Board Game', 'Strategic board-game based on the anime lore.', 'Win the board game challenges set by Solomon Muto.', 'A fun and tactical Japanese board game experience.', 'Sugoroku no Sugoroku features unique RPG elements and board-based strategy. Play through themed maps and use card effects to outpace your rivals in this rare Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!---the-eternal-duelist-soul-umode7', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! - The Eternal Duelist Soul (U)(Mode7)', '2002', 'Card Battle', 'Konami', '1', 'Card Game', 'Authentic TCG simulation with official rules.', 'Defeat the legendary duelists to become the world champ.', 'The classic handheld Yu-Gi-Oh! experience.', 'Yu-Gi-Oh! The Eternal Duelist Soul features a faithful adaptation of the early card game rules. Duel against Yugi, Kaiba, and Joey to unlock booster packs and refine your deck.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!---the-sacred-cards-erising-sun', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! - The Sacred Cards (E)(Rising Sun)', '2003', 'Card Battle', 'Konami', '1', 'Card Game', 'Story-driven TCG RPG with exploration.', 'Explore Battle City and win the Egyptian God Cards.', 'A plot-heavy RPG twist on the card game.', 'Yu-Gi-Oh! The Sacred Cards features a unique "cost" system and direct exploration. Follow the Battle City arc and duel NPCs in this atmospheric and accessible handheld RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!---the-sacred-cards-uvenom', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! - The Sacred Cards (U)(Venom)', '2003', 'Card Battle', 'Konami', '1', 'Card Game', 'Story-driven TCG RPG with exploration.', 'Explore Battle City and win the Egyptian God Cards.', 'A plot-heavy RPG twist on the card game.', 'Yu-Gi-Oh! The Sacred Cards features a unique "cost" system and direct exploration. Follow the Battle City arc and duel NPCs in this atmospheric and accessible handheld RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!---world-championship-tournament-2004-egba', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! - World Championship Tournament 2004 (E)(GBA)', '2004', 'Card Battle', 'Konami', '1', 'Card Game', 'TCG simulation with competitive tournament focus.', 'Build a winning deck to compete in the 2004 world circuit.', 'Professional and deep competitive dueling for GBA.', 'World Championship Tournament 2004 offers a massive card pool and challenging AI. Perfect your strategy and climb the rankings in this polished and essential TCG simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!---world-championship-tournament-2004-urising-sun', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! - World Championship Tournament 2004 (U)(Rising Sun)', '2004', 'Card Battle', 'Konami', '1', 'Card Game', 'TCG simulation with competitive tournament focus.', 'Build a winning deck to compete in the 2004 world circuit.', 'Professional and deep competitive dueling for GBA.', 'World Championship Tournament 2004 offers a massive card pool and challenging AI. Perfect your strategy and climb the rankings in this polished and essential TCG simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!-7-trials-to-glory---world-championship-tournament-2005-uvenom', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! 7 Trials to Glory - World Championship Tournament 2005 (U)(Venom)', '2005', 'Card Battle', 'Konami', '1', 'Card Game', 'TCG simulation with over 1,000 cards and RPG elements.', 'Win the tournament and master the 7 trials of glory.', 'A content-rich and refined Yu-Gi-Oh! title.', '7 Trials to Glory (WCT 2005) features a free-roaming world and deeper card management. Duel through various locations and build the ultimate deck in this highly-rated sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!-day-of-the-duelist---world-championship-tournament-2005-egp', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! Day Of The Duelist - World Championship Tournament 2005 (E)(GP)', '2005', 'Card Battle', 'Konami', '1', 'Card Game', 'TCG simulation with competitive tournament focus.', 'Build a winning deck to compete in the 2005 world circuit.', 'Professional and deep competitive dueling for GBA.', 'Day of the Duelist (WCT 2005) provides a streamlined and intense dueling experience. With an updated card list and faster AI, it''s a top-tier choice for hardcore fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!-destiny-board-traveler-uvenom', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! Destiny Board Traveler (U)(Venom)', '2004', 'Board Game', 'Konami', '1', 'Board Game', 'Strategy board-game with card-battle elements.', 'Navigate the board and defeat rivals in tactical duels.', 'A unique board-game spin-off of the Yu-Gi-Oh! series.', 'Yu-Gi-Oh! Destiny Board Traveler combines classic board game movement with card dueling mechanics. Strategize your placement and use your deck to dominate the field.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!-duel-monsters-5-expert-1-jeurasia', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! Duel Monsters 5 Expert 1 (J)(Eurasia)', '2001', 'Card Battle', 'Konami', '1', 'Card Game', 'TCG simulation and early handheld entry.', 'Defeat duelists from the original anime to unlock packs.', 'The foundation of the Expert series for GBA.', 'Duel Monsters 5 Expert 1 features the core rules of the early card game. Build your collection and face off against iconic characters in this classic Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!-duel-monsters-6-expert-2-jcezar', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! Duel Monsters 6 Expert 2 (J)(Cezar)', '2001', 'Card Battle', 'Konami', '1', 'Card Game', 'TCG simulation with expanded card roster.', 'Master the rules and win the expert-level tournaments.', 'A refined and expanded dueling simulation.', 'Duel Monsters 6 Expert 2 offers a more challenging AI and a broader selection of cards. It set the standard for the high-quality simulations that followed on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!-duel-monsters-7---kettou-toshi-densetsu-jcream', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! Duel Monsters 7 - Kettou Toshi Densetsu (J)(Cream)', '2002', 'Card Battle', 'Konami', '1', 'Card Game', 'Story-driven RPG focusing on the Battle City arc.', 'Collect the Rare Cards and stop the Marik''s Ghouls.', 'An epic RPG journey through the world of Yu-Gi-Oh!.', 'Duel Monsters 7 (Kettou Toshi Densetsu) is the Japanese original of The Sacred Cards. Experience the full story and tactical duels in this beautifully presented RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!-duel-monsters-8-jcezar', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! Duel Monsters 8 (J)(Cezar)', '2003', 'Card Battle', 'Konami', '1', 'Card Game', 'Story-driven RPG and sequel to the Battle City saga.', 'Stop the Resurrection of the Great Beast and save the world.', 'A deep and high-stakes Yu-Gi-Oh! RPG sequel.', 'Duel Monsters 8 (Reshef of Destruction) is known for its high difficulty and massive story. Explore the world and build a deck capable of defeating ancient evil forces.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!-duel-monsters-expert-3-jwrg', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! Duel Monsters Expert 3 (J)(WRG)', '2002', 'Card Battle', 'Konami', '1', 'Card Game', 'TCG simulation with an emphasis on competitive play.', 'Win expert matches and collect rare booster packs.', 'High-quality card battling with a polished engine.', 'Duel Monsters Expert 3 provides a smooth and fast-paced dueling experience. It features updated rules and a clean interface that made it a fan favorite in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!-duel-monsters-gx---mezase-duel-king-jsupplex', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! Duel Monsters GX - Mezase Duel King (J)(Supplex)', '2005', 'Card Battle', 'Konami', '1', 'Card Game', 'Life-sim and TCG RPG set in the Duel Academy.', 'Study hard, duel rivals, and become the King of Games.', 'The first GX-era adventure on the GBA.', 'Mezase Duel King! (GX) lets you live the life of a student at Duel Academy. Attend classes, choose your dorm, and duel through the first year of the GX story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!-duel-monsters-international-jindependent', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! Duel Monsters International (J)(Independent)', '2003', 'Card Battle', 'Konami', '1', 'Card Game', 'Multi-language TCG simulation for global players.', 'Defeat world-class duelists and build a master deck.', 'A polished international version of the card game.', 'Duel Monsters International features a multi-language interface and a solid card pool. It’s an accessible and high-quality entry point for fans of the TCG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!-duel-monsters-international-jmugs', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! Duel Monsters International (J)(Mugs)', '2003', 'Card Battle', 'Konami', '1', 'Card Game', 'Multi-language TCG simulation for global players.', 'Defeat world-class duelists and build a master deck.', 'A polished international version of the card game.', 'Duel Monsters International features a multi-language interface and a solid card pool. It’s an accessible and high-quality entry point for fans of the TCG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!-duel-monsters-international-2-jcaravan', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! Duel Monsters International 2 (J)(Caravan)', '2004', 'Card Battle', 'Konami', '1', 'Card Game', 'Expanded international TCG simulation.', 'Compete in global tournaments and master new cards.', 'The definitive international dueling experience.', 'Duel Monsters International 2 offers an even larger card selection and improved duel animations. It’s the ultimate version of the "International" sub-series for GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!-dungeon-dice-monsters-erising-sun', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! Dungeon Dice Monsters (E)(Rising Sun)', '2003', 'Strategy / Board', 'Game Freak', '2', 'Turn-Based Strategy', 'Tactical board-game with dice-summoning mechanics.', 'Use dice to build a path and defeat the opponent''s master.', 'A unique and strategic spin-off of Yu-Gi-Oh!.', 'Yu-Gi-Oh! Dungeon Dice Monsters brings the fan-favorite game from the anime to GBA. Roll dice to create monsters and terrain on a grid, mastering a completely different type of tactical duel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!-dungeon-dice-monsters-jrapid-fire', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! Dungeon Dice Monsters (J)(Rapid Fire)', '2003', 'Strategy / Board', 'Game Freak', '2', 'Turn-Based Strategy', 'Tactical board-game with dice-summoning mechanics.', 'Use dice to build a path and defeat the opponent''s master.', 'A unique and strategic spin-off of Yu-Gi-Oh!.', 'Yu-Gi-Oh! Dungeon Dice Monsters brings the fan-favorite game from the anime to GBA. Roll dice to create monsters and terrain on a grid, mastering a completely different type of tactical duel.');
