INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!-gx---duel-academy-erising-sun', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! GX - Duel Academy (E)(Rising Sun)', '2006', 'Role-Playing / Card', 'Game Freak', '2', 'Turn-Based RPG', 'Life-sim and TCG RPG set in the Duel Academy.', 'Rise through the dorm ranks to become the King of Games.', 'The definitive GX-era dueling experience for GBA.', 'Yu-Gi-Oh! GX: Duel Academy lets you experience the life of a student. Pass exams, build relationships with Jaden and friends, and master over 1,200 cards in this deep TCG simulation.');
