INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!-reshef-of-destruction-erising-sun', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! Reshef of Destruction (E)(Rising Sun)', '2003', 'Role-Playing', 'Game Freak', '1', 'Turn-Based RPG', 'Story-driven TCG RPG with exploration.', 'Stop the resurrection of the Great Beast Reshef.', 'A challenging and plot-heavy Yu-Gi-Oh! sequel.', 'Reshef of Destruction is known for its high difficulty and epic scale. Travel across the globe, manage your deck capacity, and save the world in this massive RPG follow-up.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!-reshef-of-destruction-uvenom', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! Reshef of Destruction (U)(Venom)', '2003', 'Role-Playing', 'Game Freak', '1', 'Turn-Based RPG', 'Story-driven TCG RPG with exploration.', 'Stop the resurrection of the Great Beast Reshef.', 'A challenging and plot-heavy Yu-Gi-Oh! sequel.', 'Reshef of Destruction is known for its high difficulty and epic scale. Travel across the globe, manage your deck capacity, and save the world in this massive RPG follow-up.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!-ultimate-masters-2006-erising-sun', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! Ultimate Masters 2006 (E)(Rising Sun)', '2006', 'Card / Strategy', 'Game Freak', '2', 'Card Strategy', 'High-level TCG simulation with over 2,000 cards.', 'Win the 2006 World Championship with the latest cards.', 'The absolute peak of competitive Yu-Gi-Oh! on GBA.', 'Ultimate Masters 2006 features a massive card pool and advanced AI. It remains the gold standard for handheld dueling, offering deep deck customization and expert-level challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!-ultimate-masters-2006-utrashman', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! Ultimate Masters 2006 (U)(Trashman)', '2006', 'Card / Strategy', 'Game Freak', '2', 'Card Strategy', 'High-level TCG simulation with over 2,000 cards.', 'Win the 2006 World Championship with the latest cards.', 'The absolute peak of competitive Yu-Gi-Oh! on GBA.', 'Ultimate Masters 2006 features a massive card pool and advanced AI. It remains the gold standard for handheld dueling, offering deep deck customization and expert-level challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!-worldwide-edition-eeurasia', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! Worldwide Edition (E)(Eurasia)', '2003', 'Card / Strategy', 'Game Freak', '2', 'Card Strategy', 'TCG simulation with a global tournament focus.', 'Defeat international duelists to unlock new card packs.', 'A polished and multilingual classic dueling sim.', 'Worldwide Edition (Great Escape) offers smooth gameplay and a solid card roster. Travel through different areas of the city to find rivals and perfect your deck-building skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-gi-oh!-worldwide-edition-urdg', 'GAMEBOYADVANCE', 'Yu-Gi-Oh! Worldwide Edition (U)(RDG)', '2003', 'Card / Strategy', 'Game Freak', '2', 'Card Strategy', 'TCG simulation with a global tournament focus.', 'Defeat international duelists to unlock new card packs.', 'A polished and multilingual classic dueling sim.', 'Worldwide Edition (Great Escape) offers smooth gameplay and a solid card roster. Travel through different areas of the city to find rivals and perfect your deck-building skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yushun-rhapsody-jeurasia', 'GAMEBOYADVANCE', 'Yushun Rhapsody (J)(Eurasia)', '2001', 'Role-Playing', 'Konami', '1', 'JRPG', 'Horse racing and management simulation.', 'Breed and train a champion horse to win the G1 races.', 'A deep and rhythmic Japanese horse-racing sim.', 'Yushun Rhapsody features complex breeding systems and tactical racing. Manage your stable''s legacy and master the timing of each race to reach the winner''s circle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yuure-yashiki-no-nijuuyon-jikan-jrapid-fire', 'GAMEBOYADVANCE', 'Yuure Yashiki no Nijuuyon Jikan (J)(Rapid Fire)', '2000', 'Adventure', 'Human Entertainment', '1', 'Horror Adventure', 'Top-down action-adventure with horror elements.', 'Survive 24 hours in a ghost-infested haunted mansion.', 'A spooky and atmospheric Japanese exclusive.', 'Yuure Yashiki no Nijuuyon Jikan (24 Hours in a Haunted House) tasks you with exploring eerie rooms and avoiding spirits. Use your wits to survive the night in this cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zoe-2173-testament-jeurasia', 'GAMEBOYADVANCE', 'Z.O.E. 2173 Testament (J)(Eurasia)', '2003', 'Action / Adventure', 'Konami', '1', 'Action Adventure', 'Tactical turn-based RPG with giant mecha combat.', 'Command your mecha squad to win the war on Mars.', 'Deep and strategic sci-fi combat by Konami.', 'Z.O.E. 2173 Testament (The Fist of Mars) features a unique grid-based movement system and intense anime-style battle animations. Experience an epic sci-fi story in this handheld gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zapper-epatience', 'GAMEBOYADVANCE', 'Zapper (E)(Patience)', '2002', 'Action / Shooter', 'Steel Monkeys', '1', 'Shooter', 'Isometric 3D platformer and puzzle-adventure.', 'Navigate Zapper through dangerous levels to save his brother.', 'A vibrant and challenging "Frogger-style" adventure.', 'Zapper: One Wicked Cricket features grid-based movement and electrical attacks. Solve environmental puzzles and dodge traps across multiple colorful worlds on GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zapper-udcs', 'GAMEBOYADVANCE', 'Zapper (U)(DCS)', '2002', 'Action / Shooter', 'Steel Monkeys', '1', 'Shooter', 'Isometric 3D platformer and puzzle-adventure.', 'Navigate Zapper through dangerous levels to save his brother.', 'A vibrant and challenging "Frogger-style" adventure.', 'Zapper: One Wicked Cricket features grid-based movement and electrical attacks. Solve environmental puzzles and dodge traps across multiple colorful worlds on GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zatchbell!---electric-arena-utrashman', 'GAMEBOYADVANCE', 'ZatchBell! - Electric Arena (U)(Trashman)', '2003', 'Fighting', 'Eighting', '2', 'Fighting', '2D fighting game based on the hit anime.', 'Use Mamodo spells to defeat rivals in the Electric Arena.', 'Fast-paced and flashy magical combat for GBA.', 'Zatch Bell! Electric Arena features unique tag-team mechanics between humans and Mamodo. Execute powerful spells and relive the excitement of the tournament in this polished fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zen-nippon-gt-senshuken-jcapital', 'GAMEBOYADVANCE', 'Zen-Nippon GT Senshuken (J)(Capital)', '2001', 'Racing', 'Genki', '1', 'Racing', 'Realistic GT circuit racing simulation.', 'Win the All-Japan Grand Touring Championship.', 'Intense and authentic Japanese circuit racing.', 'Zen-Nippon GT Senshuken offers licensed cars and real tracks. Master the handling of high-performance GT vehicles in this technically impressive handheld racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zen-nippon-shounen-soccer-taikai-2---mezase-nippon-ichi!-jpatience', 'GAMEBOYADVANCE', 'Zen-Nippon Shounen Soccer Taikai 2 - Mezase Nippon-ichi! (J)(Patience)', '2001', 'Sports', 'SCEI', '1', 'Soccer', 'Youth soccer simulation and management.', 'Lead your neighborhood team to the national championship.', 'Charming and strategic Japanese youth soccer.', 'Mezase Nippon-ichi! focuses on training and team spirit. Scout young talent and manage match tactics to climb the ranks of Japanese junior football.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zero-one-jmugs', 'GAMEBOYADVANCE', 'Zero One (J)(Mugs)', '2002', 'Adventure', 'MediaKite', '1', 'Adventure', 'Visual novel and mystery adventure.', 'Solve cyber-crimes in a futuristic digital world.', 'A stylish and text-heavy cyberpunk investigation.', 'Zero One features a striking art style and deep branching narratives. Uncover a high-tech conspiracy in this immersive Japanese sci-fi title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zero-one-sp-jrising-sun', 'GAMEBOYADVANCE', 'Zero One SP (J)(Rising Sun)', '2002', 'Adventure', 'MediaKite', '1', 'Adventure', 'Enhanced visual novel and mystery adventure.', 'Solve cyber-crimes in a futuristic digital world.', 'An upgraded and content-rich sci-fi mystery.', 'Zero One SP adds new scenarios and polished visuals to the original investigation. Experience the definitive version of this cyber-thriller on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zettai-zetsumei-dangerous-jiisan-2-jrising-sun', 'GAMEBOYADVANCE', 'Zettai Zetsumei Dangerous Jiisan 2 (J)(Rising Sun)', '2004', 'Action / Comedy', 'Rising Sun', '1', 'Action Platformer', 'Wacky action-adventure based on the comedy manga.', 'Complete absurd tasks and survive the Grandpa''s chaos.', 'Hilarious and bizarre Japanese humor for GBA.', 'Dangerous Jiisan 2 features a variety of surreal mini-games and platforming segments. It captures the chaotic spirit of the original manga with colorful and funny visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zettai-zetsumei-dangerous-jiisan-3-hateshinaki-mamonogatari-jcaravan', 'GAMEBOYADVANCE', 'Zettai Zetsumei Dangerous Jiisan 3 Hateshinaki Mamonogatari (J)(Caravan)', '2005', 'Action / Comedy', 'Caravan', '1', 'Action Platformer', 'RPG and action-adventure with comedy elements.', 'Explore a world of monsters and survive using wacky skills.', 'An epic and funny Japanese RPG adventure.', 'Dangerous Jiisan 3 expands the scope with a monster-hunting theme. Engage in absurd battles and explore a large world filled with the series'' signature brand of humor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zettai-zetsumei-den-chara-suji-san-jcaravan', 'GAMEBOYADVANCE', 'Zettai Zetsumei Den Chara Suji-San (J)(Caravan)', '2004', 'Action / Comedy', 'Caravan', '1', 'Action Platformer', 'Puzzle and mini-game collection starring Jiisan.', 'Solve bizarre puzzles and clear hilarious challenges.', 'A brain-teasing and funny Japanese compilation.', 'Den Chara Suji-San focuses on logic and reaction puzzles. Enjoy the strange humor of Dangerous Jiisan while testing your mental agility across various modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zettaizetsumei-dangerous-jiisan---shijou-saikyou-no-dogeza-jrising-sun', 'GAMEBOYADVANCE', 'Zettaizetsumei Dangerous Jiisan - Shijou Saikyou no Dogeza (J)(Rising Sun)', '2006', 'Action / Comedy', 'Rising Sun', '1', 'Action Platformer', 'Action-adventure with a focus on comedic "Dogeza".', 'Master the art of the grovel to survive wild situations.', 'The ultimate comedy-action experience for Jiisan fans.', 'Shijou Saikyou no Dogeza is a unique title where humble bowing is a core mechanic. Navigate through a wacky story filled with the series'' iconic characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zidane-football-generation-2002-emode7', 'GAMEBOYADVANCE', 'Zidane Football Generation 2002 (E)(Mode7)', '2001', 'Sports / Soccer', 'SCE Studio Liverpool', '1', 'Soccer Simulation', 'Top-down soccer simulation and management.', 'Lead your team to victory in the 2002 football season.', 'Fast-paced soccer action featuring Zinedine Zidane.', 'Zidane Football Generation offers arcade-style gameplay with deep team customization. Master the pitch with intuitive controls and lead your nation to global glory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zoey-101-urising-sun', 'GAMEBOYADVANCE', 'Zoey 101 (U)(Rising Sun)', '2006', 'Adventure', 'Altron', '1', 'Adventure', 'Social adventure and mini-game collection for kids.', 'Navigate the social life of Pacific Coast Academy.', 'A fun and friendly adaptation of the Nickelodeon hit.', 'Zoey 101 features various mini-games based on the show''s episodes. Help Zoey and her friends with school projects and social drama in this vibrant GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zoids-saga-ii-jmugs', 'GAMEBOYADVANCE', 'Zoid''s Saga II (J)(Mugs)', '2003', 'Role-Playing', 'Takara', '1', 'Tactical RPG', 'Turn-based tactical RPG with customizable mecha.', 'Build and battle Zoids to save the planet from destruction.', 'Deep and strategic mecha-combat for fans.', 'Zoids Saga II lets you customize massive mechanical beasts with weapons and armor. Engage in grid-based tactical battles in this content-heavy Japanese RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zoids---legacy-uvenom', 'GAMEBOYADVANCE', 'Zoids - Legacy (U)(Venom)', '2006', 'Role-Playing', 'Backbone Entertainment', '1', 'Tactical RPG', 'Turn-based tactical RPG with customizable mecha.', 'Build and battle Zoids to save the planet from destruction.', 'The western release of the deep Zoids strategy saga.', 'Zoids Legacy features an epic story mode and hundreds of parts to collect. Master tactical combat and build the ultimate Zoid team in this polished handheld RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zoids-saga-jindependent', 'GAMEBOYADVANCE', 'Zoids Saga (J)(Independent)', '2002', 'Role-Playing', 'Takara', '1', 'Tactical RPG', 'Turn-based tactical RPG with customizable mecha.', 'Build and battle Zoids to save the planet from destruction.', 'The foundation of the Zoids strategy series on GBA.', 'Zoids Saga is a classic JRPG where you command mechanical animals. Experience the origin of the handheld saga with deep customization and tactical depth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zoids-saga-fuzors-jindependent', 'GAMEBOYADVANCE', 'Zoids Saga Fuzors (J)(Independent)', '2005', 'Role-Playing', 'Takara', '1', 'Tactical RPG', 'Tactical RPG featuring characters from Zoids Fuzors.', 'Master the art of Zoid fusing to gain immense power.', 'Intense mecha-merging action and strategy for GBA.', 'Zoids Saga Fuzors adds the "Fusion" mechanic to the classic tactical gameplay. Combine your Zoids into powerful new forms to dominate the battlefield in this Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zoku-bokura-no-taiyou---taiyou-shounen-django-jcaravan', 'GAMEBOYADVANCE', 'Zoku Bokura no Taiyou - Taiyou Shounen Django (J)(Caravan)', '2004', 'Role-Playing', 'Action', 'RPG', 'Action RPG', 'Action RPG with real-time solar-sensor mechanics.', 'Hunt vampires and use solar power to purify the undead.', 'Hideo Kojima''s brilliant and innovative sun-powered sequel.', 'Zoku Bokura no Taiyou (Boktai 2) expands the solar-powered gameplay with new weapons and a deep RPG system. Use the sun to forge items and fight darkness in this stunning GBA masterpiece.');
