INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zone-of-the-enders---the-fist-of-mars-ecezar', 'GAMEBOYADVANCE', 'Zone of the Enders - The Fist of Mars (E)(Cezar)', '2001', 'Action / Strategy', 'Konami', '1', 'Real-Time Strategy', 'Tactical turn-based RPG with giant mecha combat.', 'Command your mecha squad to win the war on Mars.', 'Deep and strategic sci-fi combat by Konami.', 'Zone of the Enders: The Fist of Mars features an incredible story and tactical depth. Master the "IAS" (Interactive Actions System) to land precise hits in this handheld sci-fi epic.');
