INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zoocube-eblizzard', 'GAMEBOYADVANCE', 'ZooCube (E)(Blizzard)', '2002', 'Puzzle', 'Ignition Entertainment', '1', 'Puzzle', '3D falling-block puzzle game.', 'Rotate a central cube to match animal shapes and colors.', 'A unique and visually striking 3D puzzle challenge.', 'ZooCube is a fresh take on the puzzle genre. Rotate the cube in all directions to catch falling animals, creating matches and clearing levels in this addictive and clever title.');
