INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zooo-etrashman', 'GAMEBOYADVANCE', 'Zooo (E)(Trashman)', '2005', 'Puzzle / Arcade', 'Success', '1', 'Arcade Puzzle', 'Fast-paced tile-matching puzzle with animals.', 'Match animal faces to clear the grid before time runs out.', 'The charming GBA version of the hit puzzle game Zoo Keeper.', 'Zooo features addictive "match-three" gameplay with cute animal sprites. With multiple modes and increasing difficulty, it''s one of the most replayable puzzlers on the system.');
